<template><scroll-view scroll-x class="data-table-wrap"><view class="data-table" :style="tableStyle"><view class="data-row data-head"><text v-for="column in columns" :key="column.key">{{ column.label }}</text></view><view v-for="(row,index) in rows" :key="row[rowKey] || index" class="data-row" @click="$emit('row-click',row)"><view v-for="column in columns" :key="column.key" class="data-cell"><slot :name="`cell-${column.key}`" :row="row" :value="row[column.key]" :index="index"><text>{{ row[column.key] ?? '—' }}</text></slot></view></view></view></scroll-view></template>
<script setup>import { computed } from 'vue'; const props=defineProps({ columns:{type:Array,default:()=>[]},rows:{type:Array,default:()=>[]},rowKey:{type:String,default:'_id'},minWidth:{type:String,default:'960px'} }); defineEmits(['row-click']); const tableStyle=computed(()=>({minWidth:props.minWidth,'--table-columns':props.columns.map((item)=>item.width||'minmax(120px,1fr)').join(' ')}));</script>
<style scoped>.data-table-wrap{background:#fff;border:1px solid var(--es-border-soft);border-radius:var(--es-radius);box-shadow:var(--es-glow);overflow:hidden}.data-table{display:block}.data-row{display:grid;grid-template-columns:var(--table-columns);min-height:58px;align-items:center;border-bottom:1px solid var(--es-border-soft)}.data-row:last-child{border-bottom:0}.data-row:not(.data-head):hover{background:#fafbff}.data-head{min-height:44px;color:var(--es-text-dim);font-size:12px;font-weight:650;background:#f9fafb}.data-head>text,.data-cell{padding:10px 14px}.data-cell{min-width:0;color:var(--es-text);font-size:13px}.data-cell text{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}</style>
